#!/usr/bin/env node
/**
 * Advance the build number for the next store upload.
 *
 * Google Play refuses an upload whose android.versionCode it has already seen, and App Store
 * Connect does the same for ios.buildNumber within one version. Both are kept in app.json as
 * one number, so a build of either platform from the same commit carries the same identity.
 * ios/ and android/ are generated by prebuild, so app.json is the only place they live.
 *
 * expo.version is the human-facing string and is not touched here; see docs/RELEASING.md.
 *
 * Usage: node scripts/bump-build.mjs
 */

import { readFileSync, writeFileSync } from 'node:fs';

const APP_JSON = new URL('../app.json', import.meta.url);

const config = JSON.parse(readFileSync(APP_JSON, 'utf8'));
const { ios, android } = config.expo;

if (!Number.isInteger(android.versionCode) || String(android.versionCode) !== ios.buildNumber) {
  console.error(
    `app.json is out of step: android.versionCode is ${JSON.stringify(android.versionCode)}, ` +
      `ios.buildNumber is ${JSON.stringify(ios.buildNumber)}. Fix it by hand before bumping.`,
  );
  process.exit(1);
}

const next = android.versionCode + 1;
android.versionCode = next;
ios.buildNumber = String(next);
writeFileSync(APP_JSON, JSON.stringify(config, null, 2) + '\n');
console.log(`Build ${next} (version ${config.expo.version}).`);
